## Submitted testbench
```systemverilog
// Target: R13_rx_resync_after_frame_error (covers/R13.sv)
//
// Stimulus: a malformed 8N1 frame whose stop bit is LOW. The frame_error
// strobe is then one clock high while rxd_reg is still low, so cov_R13 arms
// (st <= 1) and, because frame_error is high on that very clock, the
// (bit_cnt == 0 && !frame_error) clear does not disarm it. The receiver
// restarts a new frame immediately on the same low line, runs bit_cnt
// 10..1 with no disarming window, and the second frame (8'hA5, good stop)
// completes while st is still 1 -> the cover fires on $rose(m_axis_tvalid)
// with m_axis_tdata == 8'hA5.
//
// Timing (prescale = 5, 40 clocks/bit, transitions on falling edges):
//   level 0        : start1 (low)
//   levels 1..8    : frame 1 data (discarded on the framing error)
//   levels 9..10   : frame 1 stop (low) + frame 2 start (line stays low)
//   levels 11..18  : 8'hA5 LSB-first
//   level 19       : frame 2 stop (high) -> A5 is delivered
`timescale 1ns / 1ps

module tb;

  localparam int CLK_PERIOD = 8;          // 125 MHz
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic [7:0]  s_axis_tdata = '0;
  logic        s_axis_tvalid = 1'b0;
  logic        s_axis_tready;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready = 1'b1;
  logic        rxd = 1'b1;
  logic        txd;
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;
  logic [15:0] prescale = PRESCALE;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  // ---------------- mid-cycle monitor (race free, catches 1-clk pulses) -----
  bit frame_error_seen = 1'b0;
  bit a5_delivered     = 1'b0;

  always @(negedge clk) begin
    if (!rst) begin
      if (rx_frame_error)                           frame_error_seen = 1'b1;
      if (m_axis_tvalid && (m_axis_tdata == 8'hA5)) a5_delivered     = 1'b1;
    end
  end

  // ---------------- stimulus helpers (all edges on falling clock) -----------
  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b0; wait_clks(2);
    rst = 1'b1; wait_clks(2);
    rst = 1'b0; wait_clks(2);
  endtask

  // Hold rxd at lvl for n_clks rising edges.
  task automatic drive_rxd(input logic lvl, input int n_clks);
    rxd = lvl;
    wait_clks(n_clks);
  endtask

  // ---------------- test sequence -------------------------------------------
  logic [7:0] word;

  initial begin
    int bit_clks;

    bit_clks = int'(PRESCALE) * 8;   // 40 clocks per UART bit at prescale 5

    do_reset();
    wait_clks(1);

    // --- Frame 1: start + data + LOW stop -> frame error ------------------
    drive_rxd(1'b0, bit_clks);                       // start1
    for (int i = 0; i < 8; i++) drive_rxd(1'b0, bit_clks);  // discarded data

    // --- Line stays low: frame 1 stop (low) + frame 2 start ---------------
    drive_rxd(1'b0, 2 * bit_clks);

    // --- Frame 2: 8'hA5 LSB-first with a good (high) stop bit -------------
    word = 8'hA5;
    for (int i = 0; i < 8; i++) drive_rxd(word[i], bit_clks);
    drive_rxd(1'b1, bit_clks + 20);                  // stop2 + idle mark

    // --- Wait for the framing error and the resynchronised A5 delivery ----
    for (int i = 0; i < 4000; i++) begin
      if (frame_error_seen && a5_delivered) break;
      @(negedge clk);
    end

    if (!frame_error_seen || !a5_delivered) begin
      $display("FAIL: frame_error_seen=%0b a5_delivered=%0b",
               frame_error_seen, a5_delivered);
      $fatal(1, "R13 sequence not observed");
    end

    $display("PASS tb R13: frame error resync delivered 0xA5");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
